SELECT salesman_user.id as salesmanid, salesman_user.username as salesmanName, (SELECT MAX(u2.agent) FROM tb_user u2 WHERE u2.salesmanid = salesman_user.id) as agent, (SELECT MAX(agent_user2.username) FROM tb_user u2 LEFT JOIN sys_user agent_user2 ON u2.agent = agent_user2.id WHERE u2.salesmanid = salesman_user.id) as agentName, COALESCE(( SELECT SUM(c.real_amount) FROM tb_user u LEFT JOIN tb_charge_order c ON u.id = c.user_id AND c.state = 1
AND c.create_time >= FROM_UNIXTIME(#{params.startTime} / 1000)
AND c.create_time <= FROM_UNIXTIME(#{params.endTime} / 1000)
WHERE u.salesmanid = salesman_user.id
AND u.agent = #{params.agent}
), 0) as czRealAmount, COALESCE(( SELECT SUM(c.real_amount) FROM tb_user u LEFT JOIN tb_charge_order c ON u.id = c.user_id AND c.state = 1
AND c.create_time >= FROM_UNIXTIME(#{params.startTime} / 1000)
AND c.create_time <= FROM_UNIXTIME(#{params.endTime} / 1000)
WHERE u.salesmanid = salesman_user.id
AND u.agent = #{params.agent}
), 0) - COALESCE(( SELECT SUM(w.real_amount) FROM tb_user u LEFT JOIN tb_withdraw_order w ON u.id = w.user_id AND w.state IN (1, 2)
AND w.create_time >= FROM_UNIXTIME(#{params.startTime} / 1000)
AND w.create_time <= FROM_UNIXTIME(#{params.endTime} / 1000)
WHERE u.salesmanid = salesman_user.id
AND u.agent = #{params.agent}
), 0) as lr, COALESCE(( SELECT SUM(w.real_amount) FROM tb_user u LEFT JOIN tb_withdraw_order w ON u.id = w.user_id AND w.state IN (1, 2)
AND w.create_time >= FROM_UNIXTIME(#{params.startTime} / 1000)
AND w.create_time <= FROM_UNIXTIME(#{params.endTime} / 1000)
WHERE u.salesmanid = salesman_user.id
AND u.agent = #{params.agent}
), 0) as txRealAmount FROM sys_user salesman_user WHERE salesman_user.type = 2 AND salesman_user.status = 1
AND salesman_user.id = #{params.salesmanid}
AND EXISTS ( SELECT 1 FROM tb_user u3 WHERE u3.salesmanid = salesman_user.id AND u3.agent = #{params.currentUserId} )
AND salesman_user.id = #{params.currentUserId}
ORDER BY ${params.orderField} ${params.order}
ORDER BY salesman_user.id

SELECT COUNT(DISTINCT salesman_user.id)
FROM sys_user salesman_user
LEFT JOIN tb_user u ON u.salesmanid = salesman_user.id
WHERE salesman_user.type = 2 AND salesman_user.status = 1

    AND u.agent = #{params.agent}


    AND salesman_user.id = #{params.salesmanid}




        AND u.agent = #{params.currentUserId}


        AND salesman_user.id = #{params.currentUserId}

SELECT COALESCE(( SELECT SUM(c.real_amount) FROM tb_user u LEFT JOIN tb_charge_order c ON u.id = c.user_id AND c.state = 1
AND c.create_time >= FROM_UNIXTIME(#{params.startTime} / 1000)
AND c.create_time <= FROM_UNIXTIME(#{params.endTime} / 1000)
WHERE u.salesmanid = salesman_user.id
AND u.agent = #{params.agent}
), 0) AS czRealAmount, COALESCE(( SELECT SUM(w.real_amount) FROM tb_user u LEFT JOIN tb_withdraw_order w ON u.id = w.user_id AND w.state IN (1, 2)
AND w.create_time >= FROM_UNIXTIME(#{params.startTime} / 1000)
AND w.create_time <= FROM_UNIXTIME(#{params.endTime} / 1000)
WHERE u.salesmanid = salesman_user.id
AND u.agent = #{params.agent}
), 0) AS txRealAmount FROM sys_user salesman_user WHERE salesman_user.type = 2 AND salesman_user.status = 1
AND salesman_user.id = #{params.salesmanid}
AND EXISTS ( SELECT 1 FROM tb_user u3 WHERE u3.salesmanid = salesman_user.id AND u3.agent = #{params.currentUserId} )
AND salesman_user.id = #{params.currentUserId}

