UPDATE tb_user 
SET
    assets = assets + #{amount},
    freeze_balance = freeze_balance - #{amount},

        cashwithdrawable = cashwithdrawable + #{amount}


        commission_balance = commission_balance + #{amount}

WHERE id = #{userId}
